    const Q = this.Q, set = (l, n) => { l.shadow.radius = Q.shR; if (l.shadow.mapSize.x !== n) { l.shadow.mapSize.set(n, n); if (l.shadow.map) { l.shadow.map.dispose(); l.shadow.map = null; } } };
    set(s, Q.near);
