      const cx = tx + f.x * R * ahead, cz = tz + f.z * R * ahead, texel = (2 * R) / size, D = 30 + tall / sn + R * ct;
      let lx = cx * r.x + cz * r.z, ly = cx * u.x + cz * u.z;
