    const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute([d.x0, 0, d.z0, d.x1, 0, d.z0, d.x1, 0, d.z1, d.x0, 0, d.z1], 3)); g.setIndex([0, 2, 1, 0, 3, 2]); geos.push(g);
