if (!LOWQ) for (const [k, f] of Object.entries(HDRI_SETS)) Assets.need('hdri/' + k, 'hdri/' + f + '_1k.hdr', { tier: 'stream', prio: ['dusk', 'city', 'night'].includes(k) ? 0 : k === 'day' ? 1 : 12 });
