  for (let k = 0; k < 2; k++) parts.push(gpart(new THREE.TorusGeometry(0.36 * s, 0.012 * s, 3, 14), 0x9a1810, x, y, z, 0, (k / 2) * Math.PI + 0.4, 0, 1, 0.92, 1));
