      if (t > 0) { this.quad(f0, f1, e1, e0, EC, 0); this.quad(i0, i1, f1, f0, 0x3a3634, 0); } else { this.quad(f1, f0, e0, e1, EC, 0); this.quad(i1, i0, f0, f1, 0x3a3634, 0); }
