          const i = randi(0, 31), u0 = (i % 4) / 4, v0 = 1 - (Math.floor(i / 4) + 1) / 8, du = 0.25, dv = 0.125;
          const cs = Math.cos(sg.rot), sn = Math.sin(sg.rot), hw = sg.w / 2, hh = sg.h / 2;
