      p.si *= lerp(1, X.sun, w); p.mi *= lerp(1, X.sun, w); p.hi *= lerp(1, X.hemi, w); p.sunVis *= lerp(1, X.vis, w);
      p.sat *= lerp(1, X.sat, w); p.ex *= lerp(1, X.ex, w); p.cl = lerp(p.cl, X.cl, w);
      for (let j = 0; j < 3; j++) p.tint[j] *= lerp(1, X.tint[j], w);
