      if (s.shot && this.opts.camera !== false) this.setShot(s.shot);
      if (s.say !== undefined) { if (this.skipping) continue; this.showLine(s); return; }
      if (s.wait) { if (this.skipping) continue; this.waitT = s.wait; return; }
