  Roads.nodes.forEach((n, i) => { if (!drivable(n)) return; const k = Math.floor(n.x / 24) * 100003 + Math.floor(n.z / 24); (_nodeHash.get(k) || _nodeHash.set(k, []).get(k)).push(i); });
