    let [h, d] = this.OFF[P.mode] || this.OFF.human;
    h *= 0.86; d *= 1.04;
    if (Interiors.cur) [h, d] = [17 * 1.015, 12 * 1.04];
    if (Boss.cur && Boss.cur.kind === 'klaude') { h += 10; d += 6; }
