      const I = Interiors.built[Interiors.cur]; if (!I) return D;
      const m = 0.7, x0 = I.b.x - I.w / 2 + m, x1 = I.b.x + I.w / 2 - m, z0 = I.b.z - I.d / 2 + m, z1 = I.b.z + I.d / 2 + 2.5;
