      const vx = P.vel.x, vz = P.vel.z, v = hyp(vx, vz);
      if (v > 3 && (vx * Math.sin(this.yaw) + vz * Math.cos(this.yaw)) / v > 0.88) this.yaw = dampA(this.yaw, Math.atan2(vx, vz), 1.1, rdt);
