        const room = this.q[0].room, n = G.started ? 2 : 8, cap = G.started ? 16 : 48, B = this.cur = [], tops = new Set(), rest = [];
        for (const it of this.q) if (B.length < n && it.room === room) { B.push(it); tops.add(it.top); } else rest.push(it);
